package com.bookstore.order.entity;
import jakarta.persistence.*; import com.bookstore.user.entity.User; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="orders") public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id") private User user; @Column(name="customer_name",nullable=false) private String customerName; @Column(name="customer_email",nullable=false) private String customerEmail; @Column(name="shipping_address") private String shippingAddress; private String phone; @Column(name="total_amount",nullable=false) private BigDecimal totalAmount; @Column(nullable=false) private String status="PENDING"; @Column(name="created_at",nullable=false) private LocalDateTime createdAt=LocalDateTime.now(); @OneToMany(mappedBy="order",cascade=CascadeType.ALL) private List<OrderItem> items=new ArrayList<>(); public Long getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getCustomerName(){return customerName;} public void setCustomerName(String v){customerName=v;} public String getCustomerEmail(){return customerEmail;} public String getShippingAddress(){return shippingAddress;} public void setShippingAddress(String v){shippingAddress=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public void setCustomerEmail(String v){customerEmail=v;} public BigDecimal getTotalAmount(){return totalAmount;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public String getStatus(){return status;} public LocalDateTime getCreatedAt(){return createdAt;} public List<OrderItem> getItems(){return items;} }
